insert into public.patterns (text_i18n, pack_id, is_free) values
  ('{"en":"Touch your ear every time before you answer a question.","el":"Άγγιξε το αυτί σου κάθε φορά πριν απαντήσεις σε μια ερώτηση.","fr":"Touche-toi l''oreille à chaque fois avant de répondre à une question.","it":"Toccati l''orecchio ogni volta prima di rispondere a una domanda.","es":"Tócate la oreja cada vez antes de responder una pregunta.","ru":"Каждый раз перед ответом на вопрос трогай себя за ухо.","de":"Berühre dir jedes Mal das Ohr, bevor du eine Frage beantwortest."}'::jsonb, (select id from public.packs where name = 'Starter Pack'), true),
  ('{"en":"Answer every question as if you are five years old.","el":"Απάντα σε κάθε ερώτηση σαν να είσαι πέντε χρονών.","fr":"Réponds à chaque question comme si tu avais cinq ans.","it":"Rispondi a ogni domanda come se avessi cinque anni.","es":"Responde a cada pregunta como si tuvieras cinco años.","ru":"Отвечай на каждый вопрос так, будто тебе пять лет.","de":"Beantworte jede Frage, als wärst du fünf Jahre alt."}'::jsonb, (select id from public.packs where name = 'Starter Pack'), true),
  ('{"en":"Copy the mannerism of the person to your left before answering.","el":"Αντέγραψε τη συνήθεια του ατόμου στα αριστερά σου πριν απαντήσεις.","fr":"Copie le tic de la personne à ta gauche avant de répondre.","it":"Copia il tic della persona alla tua sinistra prima di rispondere.","es":"Copia el gesto de la persona a tu izquierda antes de responder.","ru":"Перед ответом копируй жест человека слева от тебя.","de":"Kopiere die Angewohnheit der Person zu deiner Linken, bevor du antwortest."}'::jsonb, (select id from public.packs where name = 'Starter Pack'), true),
  ('{"en":"End every answer with a question of your own.","el":"Τελείωνε κάθε απάντηση με μια δική σου ερώτηση.","fr":"Termine chaque réponse par une question de ton cru.","it":"Termina ogni risposta con una domanda tua.","es":"Termina cada respuesta con una pregunta propia.","ru":"Заканчивай каждый ответ своим встречным вопросом.","de":"Beende jede Antwort mit einer eigenen Gegenfrage."}'::jsonb, (select id from public.packs where name = 'Starter Pack'), true),
  ('{"en":"Speak in the third person about yourself.","el":"Μίλα για τον εαυτό σου σε τρίτο πρόσωπο.","fr":"Parle de toi à la troisième personne.","it":"Parla di te stesso in terza persona.","es":"Habla de ti mismo en tercera persona.","ru":"Говори о себе в третьем лице.","de":"Sprich in der dritten Person über dich selbst."}'::jsonb, (select id from public.packs where name = 'Starter Pack'), true),
  ('{"en":"Pause and count to three (silently) before every answer.","el":"Κάνε μια παύση και μέτρα ως το τρία (σιωπηλά) πριν από κάθε απάντηση.","fr":"Fais une pause et compte jusqu''à trois (en silence) avant chaque réponse.","it":"Fai una pausa e conta fino a tre (in silenzio) prima di ogni risposta.","es":"Haz una pausa y cuenta hasta tres (en silencio) antes de cada respuesta.","ru":"Перед каждым ответом делай паузу и (про себя) считай до трёх.","de":"Mach eine Pause und zähle (leise) bis drei, bevor du antwortest."}'::jsonb, (select id from public.packs where name = 'Starter Pack'), true),
  ('{"en":"Answer as though you are extremely offended by the question.","el":"Απάντα σαν να έχεις προσβληθεί πολύ από την ερώτηση.","fr":"Réponds comme si tu étais extrêmement vexé(e) par la question.","it":"Rispondi come se fossi estremamente offeso dalla domanda.","es":"Responde como si estuvieras sumamente ofendido por la pregunta.","ru":"Отвечай так, будто вопрос тебя крайне оскорбил.","de":"Antworte, als wärst du von der Frage zutiefst beleidigt."}'::jsonb, (select id from public.packs where name = 'Starter Pack'), true),
  ('{"en":"Cross and uncross your arms before each answer.","el":"Σταύρωνε και ξεσταύρωνε τα χέρια σου πριν από κάθε απάντηση.","fr":"Croise et décroise les bras avant chaque réponse.","it":"Incrocia e scrocia le braccia prima di ogni risposta.","es":"Cruza y descruza los brazos antes de cada respuesta.","ru":"Перед каждым ответом скрещивай и расскрещивай руки.","de":"Verschränke und entschränke die Arme vor jeder Antwort."}'::jsonb, (select id from public.packs where name = 'Starter Pack'), true),
  ('{"en":"Compliment the Guesser before every answer.","el":"Κάνε ένα κομπλιμέντο σε αυτόν που μαντεύει πριν από κάθε απάντηση.","fr":"Fais un compliment à celui ou celle qui devine avant chaque réponse.","it":"Fai un complimento a chi indovina prima di ogni risposta.","es":"Haz un cumplido a quien adivina antes de cada respuesta.","ru":"Перед каждым ответом делай комплимент угадывающему.","de":"Mach dem Rater vor jeder Antwort ein Kompliment."}'::jsonb, (select id from public.packs where name = 'Starter Pack'), true),
  ('{"en":"Answer every question with another question.","el":"Απάντα σε κάθε ερώτηση με άλλη ερώτηση.","fr":"Réponds à chaque question par une autre question.","it":"Rispondi a ogni domanda con un''altra domanda.","es":"Responde a cada pregunta con otra pregunta.","ru":"Отвечай на каждый вопрос ещё одним вопросом.","de":"Beantworte jede Frage mit einer weiteren Frage."}'::jsonb, (select id from public.packs where name = 'Starter Pack'), true),
  ('{"en":"Lean in close like you are sharing a secret for every answer.","el":"Έλα κοντά σαν να μοιράζεσαι ένα μυστικό σε κάθε απάντηση.","fr":"Penche-toi comme si tu confiais un secret à chaque réponse.","it":"Sporgiti come se stessi condividendo un segreto a ogni risposta.","es":"Inclínate como si estuvieras compartiendo un secreto en cada respuesta.","ru":"Наклоняйся вперёд, будто делишься секретом, перед каждым ответом.","de":"Beuge dich vor, als würdest du bei jeder Antwort ein Geheimnis verraten."}'::jsonb, (select id from public.packs where name = 'Starter Pack'), true),
  ('{"en":"Tap the table twice before you speak.","el":"Χτύπα δύο φορές το τραπέζι πριν μιλήσεις.","fr":"Tape deux fois sur la table avant de parler.","it":"Batti due volte sul tavolo prima di parlare.","es":"Golpea la mesa dos veces antes de hablar.","ru":"Дважды постучи по столу, прежде чем заговорить.","de":"Klopfe zweimal auf den Tisch, bevor du sprichst."}'::jsonb, (select id from public.packs where name = 'Starter Pack'), true),
  ('{"en":"Answer as if you are extremely bored by the whole conversation.","el":"Απάντα σαν να βαριέσαι τρομερά όλη τη συζήτηση.","fr":"Réponds comme si toute cette conversation t''ennuyait profondément.","it":"Rispondi come se fossi estremamente annoiato da tutta la conversazione.","es":"Responde como si toda la conversación te aburriera muchísimo.","ru":"Отвечай так, будто тебе смертельно скучно от всего разговора.","de":"Antworte, als würde dich das ganze Gespräch zutiefst langweilen."}'::jsonb, (select id from public.packs where name = 'Starter Pack'), true),
  ('{"en":"Refer to the Guesser by the wrong name every time.","el":"Αποκάλεσε αυτόν που μαντεύει με λάθος όνομα κάθε φορά.","fr":"Appelle la personne qui devine par le mauvais prénom à chaque fois.","it":"Chiama chi indovina con il nome sbagliato ogni volta.","es":"Llama a quien adivina por el nombre equivocado cada vez.","ru":"Каждый раз называй угадывающего не тем именем.","de":"Nenne den Rater jedes Mal beim falschen Namen."}'::jsonb, (select id from public.packs where name = 'Starter Pack'), true),
  ('{"en":"Answer everything like you are a game show host.","el":"Απάντα σε όλα σαν παρουσιαστής τηλεπαιχνιδιού.","fr":"Réponds à tout comme un animateur de jeu télévisé.","it":"Rispondi a tutto come un presentatore di un game show.","es":"Responde a todo como un presentador de concursos de televisión.","ru":"Отвечай на всё, как ведущий телевизионного шоу.","de":"Beantworte alles wie ein Gameshow-Moderator."}'::jsonb, (select id from public.packs where name = 'Starter Pack'), true),
  ('{"en":"Glance at your wrist like you are checking a watch before answering.","el":"Κοίτα τον καρπό σου σαν να ελέγχεις την ώρα πριν απαντήσεις.","fr":"Regarde ton poignet comme si tu vérifiais l''heure avant de répondre.","it":"Guarda il polso come se controllassi l''ora prima di rispondere.","es":"Mira tu muñeca como si estuvieras comprobando la hora antes de responder.","ru":"Перед ответом посмотри на запястье, будто проверяешь время.","de":"Schau auf dein Handgelenk, als würdest du die Uhrzeit prüfen, bevor du antwortest."}'::jsonb, (select id from public.packs where name = 'Starter Pack'), true),
  ('{"en":"Answer as if you just woke up from a nap.","el":"Απάντα σαν να μόλις ξύπνησες από έναν υπνάκο.","fr":"Réponds comme si tu venais tout juste de te réveiller d''une sieste.","it":"Rispondi come se ti fossi appena svegliato da un pisolino.","es":"Responde como si te acabaras de despertar de una siesta.","ru":"Отвечай так, будто только что проснулся после дневного сна.","de":"Antworte, als wärst du gerade erst aus einem Nickerchen aufgewacht."}'::jsonb, (select id from public.packs where name = 'Starter Pack'), true),
  ('{"en":"Clear your throat before every single answer.","el":"Καθάρισε το λαιμό σου πριν από κάθε απάντηση.","fr":"Éclaircis-toi la gorge avant chaque réponse.","it":"Schiarisciti la voce prima di ogni singola risposta.","es":"Aclárate la garganta antes de cada respuesta.","ru":"Прочищай горло перед каждым ответом.","de":"Räuspere dich vor jeder einzelnen Antwort."}'::jsonb, (select id from public.packs where name = 'Starter Pack'), true),
  ('{"en":"Answer every question with overly dramatic sighs.","el":"Απάντα σε κάθε ερώτηση με υπερβολικά δραματικούς αναστεναγμούς.","fr":"Réponds à chaque question avec des soupirs très théâtraux.","it":"Rispondi a ogni domanda con sospiri estremamente drammatici.","es":"Responde a cada pregunta con suspiros muy dramáticos.","ru":"Отвечай на каждый вопрос с преувеличенно драматичными вздохами.","de":"Beantworte jede Frage mit übertrieben dramatischem Seufzen."}'::jsonb, (select id from public.packs where name = 'Starter Pack'), true),
  ('{"en":"Point at the ceiling briefly before answering.","el":"Δείξε σύντομα το ταβάνι πριν απαντήσεις.","fr":"Pointe brièvement le plafond avant de répondre.","it":"Indica brevemente il soffitto prima di rispondere.","es":"Señala brevemente el techo antes de responder.","ru":"Перед ответом ненадолго укажи пальцем в потолок.","de":"Zeige kurz zur Decke, bevor du antwortest."}'::jsonb, (select id from public.packs where name = 'Starter Pack'), true),
  ('{"en":"Answer as though you are a news anchor delivering breaking news.","el":"Απάντα σαν παρουσιαστής ειδήσεων που ανακοινώνει έκτακτο δελτίο.","fr":"Réponds comme un présentateur du journal annonçant une information de dernière minute.","it":"Rispondi come un anchorman che annuncia una notizia dell''ultima ora.","es":"Responde como un presentador de noticias anunciando una noticia de última hora.","ru":"Отвечай как диктор новостей, объявляющий срочную новость.","de":"Antworte wie ein Nachrichtensprecher, der Eilmeldungen verkündet."}'::jsonb, (select id from public.packs where name = 'Starter Pack'), true),
  ('{"en":"Fix your hair or collar before every answer.","el":"Φτιάξε τα μαλλιά σου ή τον γιακά σου πριν από κάθε απάντηση.","fr":"Arrange tes cheveux ou ton col avant chaque réponse.","it":"Sistemati i capelli o il colletto prima di ogni risposta.","es":"Arréglate el pelo o el cuello antes de cada respuesta.","ru":"Поправляй волосы или воротник перед каждым ответом.","de":"Richte deine Haare oder deinen Kragen vor jeder Antwort."}'::jsonb, (select id from public.packs where name = 'Starter Pack'), true),
  ('{"en":"Answer every question as if it is the best question you''ve ever heard.","el":"Απάντα σε κάθε ερώτηση σαν να είναι η καλύτερη ερώτηση που έχεις ακούσει ποτέ.","fr":"Réponds à chaque question comme si c''était la meilleure question jamais posée.","it":"Rispondi a ogni domanda come se fosse la domanda più bella che tu abbia mai sentito.","es":"Responde a cada pregunta como si fuera la mejor pregunta que has escuchado en tu vida.","ru":"Отвечай на каждый вопрос так, будто это лучший вопрос, который ты когда-либо слышал.","de":"Beantworte jede Frage, als wäre es die beste Frage, die du je gehört hast."}'::jsonb, (select id from public.packs where name = 'Starter Pack'), true),
  ('{"en":"Whisper the first word of every answer.","el":"Ψιθύρισε την πρώτη λέξη κάθε απάντησης.","fr":"Chuchote le premier mot de chaque réponse.","it":"Sussurra la prima parola di ogni risposta.","es":"Susurra la primera palabra de cada respuesta.","ru":"Шёпотом произноси первое слово каждого ответа.","de":"Flüstere das erste Wort jeder Antwort."}'::jsonb, (select id from public.packs where name = 'Starter Pack'), true),
  ('{"en":"Answer as if you are trying to sell the Guesser something.","el":"Απάντα σαν να προσπαθείς να πουλήσεις κάτι σε αυτόν που μαντεύει.","fr":"Réponds comme si tu essayais de vendre quelque chose à celui ou celle qui devine.","it":"Rispondi come se stessi cercando di vendere qualcosa a chi indovina.","es":"Responde como si intentaras venderle algo a quien adivina.","ru":"Отвечай так, будто пытаешься что-то продать угадывающему.","de":"Antworte, als würdest du versuchen, dem Rater etwas zu verkaufen."}'::jsonb, (select id from public.packs where name = 'Starter Pack'), true),
  ('{"en":"Nod slowly three times before you start answering.","el":"Κούνησε το κεφάλι σου αργά τρεις φορές πριν αρχίσεις να απαντάς.","fr":"Hoche la tête lentement trois fois avant de commencer à répondre.","it":"Annuisci lentamente tre volte prima di iniziare a rispondere.","es":"Asiente lentamente tres veces antes de empezar a responder.","ru":"Медленно кивни три раза, прежде чем начать отвечать.","de":"Nicke langsam dreimal, bevor du zu antworten beginnst."}'::jsonb, (select id from public.packs where name = 'Starter Pack'), true),
  ('{"en":"Answer every question like you are being interviewed for a documentary.","el":"Απάντα σε κάθε ερώτηση σαν να σε συνεντεύξιαζαν για ντοκιμαντέρ.","fr":"Réponds à chaque question comme si tu étais interviewé(e) pour un documentaire.","it":"Rispondi a ogni domanda come se fossi intervistato per un documentario.","es":"Responde a cada pregunta como si te estuvieran entrevistando para un documental.","ru":"Отвечай на каждый вопрос так, будто тебя интервьюируют для документального фильма.","de":"Beantworte jede Frage, als würdest du für eine Dokumentation interviewt."}'::jsonb, (select id from public.packs where name = 'Starter Pack'), true),
  ('{"en":"Snap your fingers before you answer, like you just remembered something.","el":"Τρίξε τα δάχτυλά σου πριν απαντήσεις, σαν να μόλις θυμήθηκες κάτι.","fr":"Claque des doigts avant de répondre, comme si tu venais de te souvenir de quelque chose.","it":"Schiocca le dita prima di rispondere, come se ti fossi appena ricordato qualcosa.","es":"Chasquea los dedos antes de responder, como si acabaras de recordar algo.","ru":"Щёлкни пальцами перед ответом, будто только что что-то вспомнил.","de":"Schnippe mit den Fingern, bevor du antwortest, als hättest du dich gerade an etwas erinnert."}'::jsonb, (select id from public.packs where name = 'Starter Pack'), true),
  ('{"en":"Answer as if you are mildly suspicious of the Guesser.","el":"Απάντα σαν να είσαι ελαφρώς καχύποπτος απέναντι σε αυτόν που μαντεύει.","fr":"Réponds comme si tu étais légèrement méfiant(e) envers celui ou celle qui devine.","it":"Rispondi come se fossi leggermente sospettoso nei confronti di chi indovina.","es":"Responde como si sospecharas un poco de quien adivina.","ru":"Отвечай так, будто немного подозреваешь угадывающего.","de":"Antworte, als wärst du dem Rater gegenüber leicht misstrauisch."}'::jsonb, (select id from public.packs where name = 'Starter Pack'), true),
  ('{"en":"End every answer by saying \"...if that makes sense.\"","el":"Τελείωνε κάθε απάντηση λέγοντας: «...αν αυτό βγάζει νόημα».","fr":"Termine chaque réponse en disant : « ... si ça a du sens. »","it":"Termina ogni risposta dicendo: \"...se ha senso.\"","es":"Termina cada respuesta diciendo: \"...si eso tiene sentido.\"","ru":"Заканчивай каждый ответ словами: «...если это имеет смысл».","de":"Beende jede Antwort mit den Worten: „...falls das Sinn ergibt.“"}'::jsonb, (select id from public.packs where name = 'Starter Pack'), true);
insert into public.patterns (text_i18n, pack_id, is_free) values
  ('{"en":"Deliver every answer like you''re in a slow-motion action shot."}'::jsonb, (select id from public.packs where name = 'Movies & Celebrities Pack'), false),
  ('{"en":"Flip imaginary sunglasses on before answering."}'::jsonb, (select id from public.packs where name = 'Movies & Celebrities Pack'), false),
  ('{"en":"Pause dramatically before every sentence, like a movie trailer voice."}'::jsonb, (select id from public.packs where name = 'Movies & Celebrities Pack'), false),
  ('{"en":"Answer as if a camera crew is filming your best angle."}'::jsonb, (select id from public.packs where name = 'Movies & Celebrities Pack'), false),
  ('{"en":"Do a subtle hair flip before speaking, like a red carpet moment."}'::jsonb, (select id from public.packs where name = 'Movies & Celebrities Pack'), false),
  ('{"en":"Speak like you''re delivering an Oscar acceptance speech."}'::jsonb, (select id from public.packs where name = 'Movies & Celebrities Pack'), false),
  ('{"en":"Glance off camera like you''re waiting for direction."}'::jsonb, (select id from public.packs where name = 'Movies & Celebrities Pack'), false),
  ('{"en":"Answer every question like it''s a plot twist reveal."}'::jsonb, (select id from public.packs where name = 'Movies & Celebrities Pack'), false),
  ('{"en":"Do a small villain smirk after every answer."}'::jsonb, (select id from public.packs where name = 'Movies & Celebrities Pack'), false),
  ('{"en":"Act like you''re the secret agent in the room, subtly scanning for exits."}'::jsonb, (select id from public.packs where name = 'Movies & Celebrities Pack'), false),
  ('{"en":"Answer questions like you''re a movie detective solving a case."}'::jsonb, (select id from public.packs where name = 'Movies & Celebrities Pack'), false),
  ('{"en":"Do a dramatic sigh before every answer, like a heartbroken lead."}'::jsonb, (select id from public.packs where name = 'Movies & Celebrities Pack'), false),
  ('{"en":"Speak as if there''s a dramatic musical swell behind you."}'::jsonb, (select id from public.packs where name = 'Movies & Celebrities Pack'), false),
  ('{"en":"Act mildly annoyed, like a diva interrupted mid-interview."}'::jsonb, (select id from public.packs where name = 'Movies & Celebrities Pack'), false),
  ('{"en":"Answer like you''re in a black-and-white noir film."}'::jsonb, (select id from public.packs where name = 'Movies & Celebrities Pack'), false),
  ('{"en":"Do a subtle \"and... action\" hand gesture before speaking."}'::jsonb, (select id from public.packs where name = 'Movies & Celebrities Pack'), false),
  ('{"en":"Treat every answer like your character''s big monologue moment."}'::jsonb, (select id from public.packs where name = 'Movies & Celebrities Pack'), false),
  ('{"en":"Act as if you just heard \"cut!\" and are slightly out of character."}'::jsonb, (select id from public.packs where name = 'Movies & Celebrities Pack'), false),
  ('{"en":"Answer like a superhero giving a serious warning."}'::jsonb, (select id from public.packs where name = 'Movies & Celebrities Pack'), false),
  ('{"en":"End every answer with a subtle wink, like a movie hero walking away."}'::jsonb, (select id from public.packs where name = 'Movies & Celebrities Pack'), false);
insert into public.patterns (text_i18n, pack_id, is_free) values
  ('{"en":"Compliment something about the person you''re answering before each answer."}'::jsonb, (select id from public.packs where name = 'Flirty & Cheeky'), false),
  ('{"en":"Bite your lip slightly before speaking."}'::jsonb, (select id from public.packs where name = 'Flirty & Cheeky'), false),
  ('{"en":"Show some skin while you answer."}'::jsonb, (select id from public.packs where name = 'Flirty & Cheeky'), false),
  ('{"en":"Lightly touch the arm of whoever is sitting closest to you."}'::jsonb, (select id from public.packs where name = 'Flirty & Cheeky'), false),
  ('{"en":"Wink at someone new after every answer."}'::jsonb, (select id from public.packs where name = 'Flirty & Cheeky'), false),
  ('{"en":"Lean in slightly closer than normal when answering."}'::jsonb, (select id from public.packs where name = 'Flirty & Cheeky'), false),
  ('{"en":"Fan yourself dramatically like they said something hot."}'::jsonb, (select id from public.packs where name = 'Flirty & Cheeky'), false),
  ('{"en":"Answer every question like you''re flirting with the asker."}'::jsonb, (select id from public.packs where name = 'Flirty & Cheeky'), false),
  ('{"en":"Gently tap the shoulder of the person to your left before speaking."}'::jsonb, (select id from public.packs where name = 'Flirty & Cheeky'), false),
  ('{"en":"Speak in a slightly lower, teasing tone than usual."}'::jsonb, (select id from public.packs where name = 'Flirty & Cheeky'), false),
  ('{"en":"Play with your collar or sleeve while thinking of an answer."}'::jsonb, (select id from public.packs where name = 'Flirty & Cheeky'), false),
  ('{"en":"Give a slow, playful smile before every answer."}'::jsonb, (select id from public.packs where name = 'Flirty & Cheeky'), false),
  ('{"en":"Answer as if you''re trying to impress a crush."}'::jsonb, (select id from public.packs where name = 'Flirty & Cheeky'), false),
  ('{"en":"Brush your hand against the table dramatically before speaking."}'::jsonb, (select id from public.packs where name = 'Flirty & Cheeky'), false),
  ('{"en":"Twirl an imaginary mustache like you''re plotting something smooth."}'::jsonb, (select id from public.packs where name = 'Flirty & Cheeky'), false),
  ('{"en":"Answer every question with a hint of mock jealousy."}'::jsonb, (select id from public.packs where name = 'Flirty & Cheeky'), false),
  ('{"en":"The person to your left must flirt with someone else in the room before your next answer."}'::jsonb, (select id from public.packs where name = 'Flirty & Cheeky'), false),
  ('{"en":"Bump shoulders lightly with your neighbor before speaking."}'::jsonb, (select id from public.packs where name = 'Flirty & Cheeky'), false),
  ('{"en":"Speak as if you''re trying to make someone jealous."}'::jsonb, (select id from public.packs where name = 'Flirty & Cheeky'), false),
  ('{"en":"Act like you have a crush on someone of the same gender sitting nearby."}'::jsonb, (select id from public.packs where name = 'Flirty & Cheeky'), false);
insert into public.patterns (text_i18n, pack_id, is_free) values
